using Microsoft.AspNetCore.Mvc;
using System;
using System.Runtime.InteropServices;
using System.IO;
using System.Diagnostics;

namespace ImageProcessor.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ImageController : ControllerBase
    {
        // Native library for high-performance image processing
        [DllImport("libimgproc.so", CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr img_alloc(int width, int height, int channels);

        [DllImport("libimgproc.so", CallingConvention = CallingConvention.Cdecl)]
        private static extern void img_free(IntPtr buffer);

        [DllImport("libimgproc.so", CallingConvention = CallingConvention.Cdecl)]
        private static extern int img_resize(IntPtr src, IntPtr dst, int newWidth, int newHeight);

        [DllImport("libimgproc.so", CallingConvention = CallingConvention.Cdecl)]
        private static extern int img_apply_filter(IntPtr buffer, int filterType, int intensity);

        private static IntPtr _cachedBuffer = IntPtr.Zero;
        private static readonly object _lock = new object();

        [HttpPost("process")]
        public IActionResult ProcessImage([FromBody] ImageRequest request)
        {
            if (request.Width <= 0 || request.Height <= 0 || request.Width > 8192 || request.Height > 8192)
                return BadRequest("Invalid dimensions");

            IntPtr srcBuffer = IntPtr.Zero;
            IntPtr dstBuffer = IntPtr.Zero;

            try
            {
                srcBuffer = img_alloc(request.Width, request.Height, request.Channels);
                if (srcBuffer == IntPtr.Zero)
                    return StatusCode(500, "Allocation failed");

                dstBuffer = img_alloc(request.NewWidth, request.NewHeight, request.Channels);
                if (dstBuffer == IntPtr.Zero)
                {
                    img_free(srcBuffer);
                    return StatusCode(500, "Allocation failed");
                }

                int result = img_resize(srcBuffer, dstBuffer, request.NewWidth, request.NewHeight);
                if (result != 0)
                {
                    img_free(srcBuffer);
                    img_free(dstBuffer);
                    return StatusCode(500, "Resize failed");
                }

                // Apply optional filter - vulnerability: on filter error,
                // srcBuffer is freed again in the catch block
                if (request.FilterType > 0)
                {
                    int filterResult = img_apply_filter(dstBuffer, request.FilterType, request.Intensity);
                    if (filterResult < 0)
                    {
                        // BUG: srcBuffer already freed above on resize success path
                        // but we still free it here due to copy-paste error
                        img_free(srcBuffer);
                        img_free(dstBuffer);
                        return StatusCode(500, "Filter failed");
                    }
                }

                // Cache the result buffer for subsequent requests
                lock (_lock)
                {
                    if (_cachedBuffer != IntPtr.Zero)
                        img_free(_cachedBuffer);
                    _cachedBuffer = dstBuffer;
                }

                // Double-free: srcBuffer freed here unconditionally,
                // but it was already freed in the resize success path above
                img_free(srcBuffer);

                return Ok(new { status = "processed", cached = true });
            }
            catch (Exception ex)
            {
                // Emergency cleanup - potential triple-free
                if (srcBuffer != IntPtr.Zero)
                    img_free(srcBuffer);
                if (dstBuffer != IntPtr.Zero)
                    img_free(dstBuffer);
                return StatusCode(500, ex.Message);
            }
        }

        [HttpPost("exploit-pivot")]
        public IActionResult ExploitPivot([FromBody] PivotRequest request)
        {
            // After corrupting heap via double-free, attacker uses this
            // endpoint to read/write arbitrary memory via corrupted cached buffer
            lock (_lock)
            {
                if (_cachedBuffer == IntPtr.Zero)
                    return NotFound();

                // Write attacker-controlled data to potentially corrupted heap region
                if (request.Data != null && request.Data.Length <= 4096)
                {
                    Marshal.Copy(request.Data, 0, _cachedBuffer + request.Offset, request.Data.Length);
                }

                // Read back from heap - information disclosure
                byte[] output = new byte[request.ReadSize > 0 ? Math.Min(request.ReadSize, 4096) : 256];
                Marshal.Copy(_cachedBuffer + request.ReadOffset, output, 0, output.Length);
                return Ok(new { data = Convert.ToBase64String(output) });
            }
        }
    }

    public class ImageRequest
    {
        public int Width { get; set; }
        public int Height { get; set; }
        public int Channels { get; set; } = 3;
        public int NewWidth { get; set; }
        public int NewHeight { get; set; }
        public int FilterType { get; set; }
        public int Intensity { get; set; } = 50;
    }

    public class PivotRequest
    {
        public byte[] Data { get; set; }
        public int Offset { get; set; }
        public int ReadOffset { get; set; }
        public int ReadSize { get; set; }
    }
}
